//! Embedded assets for the dashboard: Geist fonts and Tabler/Lucide icons.
//!
//! Files live under examples/apps/assets and are compiled into the binary with
//! `@embedFile`, so the app runs from any working directory. Licenses are in
//! assets/fonts/OFL-LICENSE.txt, assets/icons/LICENSE-tabler and LICENSE-lucide.
//! This file is generated from the asset directory listing.

/// Font faces, indexed by `Font`.
pub const Font = enum(u16) {
    regular,
    medium,
    semibold,
    bold,
    mono,
};

pub const font_files = [_][]const u8{
    @embedFile("assets/fonts/Geist-Regular.ttf"),
    @embedFile("assets/fonts/Geist-Medium.ttf"),
    @embedFile("assets/fonts/Geist-SemiBold.ttf"),
    @embedFile("assets/fonts/Geist-Bold.ttf"),
    @embedFile("assets/fonts/GeistMono-Regular.ttf"),
};

